            array('id' => '13','key' => 'testimonial-section','value' => '{"images":{"image":"90ec700f-a60c-43d1-9c76-ad86a96f3aba.webp"},"language":{"en":{"title":"Testimonials","heading":"What Our Customer Say","review_title":"TOTAL USER REVIEWS","sub_heading":"Join these satisfied users and experience the Anaki difference for yourself. Start trading confidently and efficiently with our state-of-the-art platform today."},"es":{"title":"Testimonios","heading":"Lo que dice nuestra cliente","review_title":"OPINIONES TOTALES DE USUARIOS","sub_heading":"\\u00danase a estos usuarios satisfechos y experimente la diferencia de Anaki por s\\u00ed mismo. Comience a operar con confianza y eficiencia con nuestra plataforma de \\u00faltima generaci\\u00f3n hoy."},"ar":{"title":"\\u0627\\u0644\\u0634\\u0647\\u0627\\u062f\\u0627\\u062a - \\u0627\\u0644\\u062a\\u0648\\u0635\\u064a\\u0627\\u062a","heading":"\\u0645\\u0627\\u0630\\u0627 \\u064a\\u0642\\u0648\\u0644 \\u0639\\u0645\\u0644\\u0627\\u0626\\u0646\\u0627","review_title":"\\u0625\\u062c\\u0645\\u0627\\u0644\\u064a \\u0645\\u0631\\u0627\\u062c\\u0639\\u0627\\u062a \\u0627\\u0644\\u0645\\u0633\\u062a\\u062e\\u062f\\u0645","sub_heading":"\\u0627\\u0646\\u0636\\u0645 \\u0625\\u0644\\u0649 \\u0647\\u0624\\u0644\\u0627\\u0621 \\u0627\\u0644\\u0645\\u0633\\u062a\\u062e\\u062f\\u0645\\u064a\\u0646 \\u0627\\u0644\\u0631\\u0627\\u0636\\u064a\\u0646 \\u0648\\u0627\\u0633\\u062a\\u0645\\u062a\\u0639 \\u0628\\u062a\\u062c\\u0631\\u0628\\u0629 \\u062a\\u063a\\u064a\\u064a\\u0631 \\u0627\\u0644\\u0625\\u0639\\u0644\\u0627\\u0646\\u0627\\u062a \\u0628\\u0646\\u0641\\u0633\\u0643. \\u0627\\u0628\\u062f\\u0623 \\u0627\\u0644\\u062a\\u062f\\u0627\\u0648\\u0644 \\u0628\\u062b\\u0642\\u0629 \\u0648\\u0643\\u0641\\u0627\\u0621\\u0629 \\u0645\\u0639 \\u0645\\u0646\\u0635\\u062a\\u0646\\u0627 \\u0627\\u0644\\u0645\\u062a\\u0637\\u0648\\u0631\\u0629 \\u0627\\u0644\\u064a\\u0648\\u0645."}},"rating":"5","total_review":"2000","items":{"64d868988b859"