            array('id' => '16','key' => 'faq-section','value' => '{"items":{"64d8a94175011":{"language":{"en":{"question":"What is Anaki?","answer":"Anaki is a cutting-edge peer-to-peer (P2P) trading platform that connects buyers and sellers directly, facilitating seamless transactions for a wide range of goods, services, and cryptocurrencies."},"es":{"question":"\\u00bfQu\\u00e9 es Anaki?","answer":"Anaki es una plataforma de comercio peer-to-peer (P2P) de vanguardia que conecta a compradores y vendedores directamente, lo que facilita transacciones fluidas para una amplia gama de bienes, servicios y criptomonedas."},"ar":{"question":"\\u0645\\u0627 \\u0647\\u0648 \\u062a\\u063a\\u064a\\u064a\\u0631 \\u0627\\u0644\\u0625\\u0639\\u0644\\u0627\\u0646\\u061f","answer":"Anaki \\u0639\\u0628\\u0627\\u0631\\u0629 \\u0639\\u0646 \\u0645\\u0646\\u0635\\u0629 \\u062a\\u062f\\u0627\\u0648\\u0644"}},"id":"64d8a94175011"},"64d8a96cd0160":{"language":{"en":{"question":"How does Anaki work?","answer":"Anaki simplifies P2P trading by providing a user-friendly interface where buyers and sellers can list, negotiate, and complete transactions. Users can create accounts, explore the Trade Marketplace, initiate trades, negotiate terms, and execute secure transactions."},"es":{"question":"\\u00bfCu\\u00e1les son las mejores funciones y servicios que ofrecemos?","answer":"Anaki simplifica el comercio P2P al proporcionar una interfaz f\\u00e1cil de usar donde los compradores y vendedores pueden enumerar, negociar y completar transacciones. Los usuarios pueden crear cuentas, explorar Trade Marketplace, iniciar transacciones,"},"ar":{"question":"\\u0643\\u064a\\u0641 \\u064a\\u0639\\u0645\\u0644 \\u062a\\u063a\\u064a\\u064a\\u0631 \\u0627\\u0644\\u0625\\u0639\\u0644\\u0627\\u0646\\u061f","answer":"\\u064a\\u0639\\u0645\\u0644 \\u0628\\u0631\\u0646\\u0627\\u0645\\u062c Anaki \\u0639\\u0644\\u0649 \\u062a\\u0628\\u0633\\u064a\\u0637 \\u0639\\u0645\\u0644\\u064a\\u0629 \\u0627\\u0644\\u062a\\u062f\\u0627\\u0648\\u0644 \\u0639\\u0628\\u0631 \\u062a\\u0642\\u0646\\u064a\\u0629 P2P \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u062a\\u0648\\u0641\\u064a\\u0631 \\u0648\\u0627\\u062c\\u0647\\u0629 \\u0633\\u0647\\u0644\\u0629 \\u0627\\u0644\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u062d\\u064a\\u062b \\u064a\\u0645\\u0643\\u0646 \\u0644\\u0644\\u0645\\u0634\\u062a\\u0631\\u064a\\u0646 \\u0648\\u0627\\u0644\\u0628\\u0627\\u0626\\u0639\\u064a\\u0646 \\u0625\\u062f\\u0631\\u0627\\u062c \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0648\\u0627\\u0644\\u062a\\u0641\\u0627\\u0648\\u0636 \\u0628\\u0634\\u0623\\u0646\\u0647\\u0627 \\u0648\\u0625\\u0643\\u0645\\u0627\\u0644\\u0647\\u0627. \\u064a\\u0645\\u0643\\u0646 \\u0644\\u0644\\u0645\\u0633\\u062a\\u062e\\u062f\\u0645\\u064a\\u0646 \\u0625\\u0646\\u0634\\u0627\\u0621 \\u062d\\u0633\\u0627\\u0628\\u0627\\u062a\\u060c \\u0648\\u0627\\u0633\\u062a\\u0643\\u0634\\u0627\\u0641 \\u0633\\u0648\\u0642 \\u0627\\u0644\\u062a\\u062c\\u0627\\u0631\\u0629\\u060c \\u0648\\u0628\\u062f\\u0621 \\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u0627\\u0644\\u062a\\u062f\\u0627\\u0648\\u0644\\u060c \\u0648\\u0627\\u0644\\u062a\\u0641\\u0627\\u0648\\u0636 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0634\\u0631"}},"id":"64d8a96cd0160"},"64de00a4c7ce8":{"language":{"en":{"question":"Is my personal information secure on Anaki?","answer":"Absolutely. We prioritize the security of your personal information. Our platform employs advanced security measures, including QRCode transactions, robust KYC protocols, and two-factor authentication (2FA), ensuring your data is protected throughout your trading journey."},"es":{"question":"\\u00bfMi informaci\\u00f3n personal est\\u00e1 segura en Anaki?","answer":"Absolutamente. Priorizamos la seguridad de su informaci\\u00f3n personal. Nuestra plataforma emplea medidas de seguridad avanzadas, que incluyen transacciones QRCode, s\\u00f3lidos protocolos KYC y autenticaci\\u00f3n de dos factores (2FA), lo que garantiza que sus datos est\\u00e9n protegidos a lo largo de su viaje comercial."},"ar":{"question":"\\u0647\\u0644 \\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a\\u064a \\u0627\\u0644\\u0634\\u062e\\u0635\\u064a\\u0629 \\u0622\\u0645\\u0646\\u0629 \\u0639\\u0644\\u0649 Anaki\\u061f","answer":"\\u0642\\u0637\\u0639\\u0627\\u064b. \\u0646\\u062d\\u0646 \\u0646\\u0639\\u0637\\u064a \\u0627\\u0644\\u0623\\u0648\\u0644\\u0648\\u064a\\u0629 \\u0644\\u0623\\u0645\\u0646 \\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a\\u0643 \\u0627\\u0644\\u0634\\u062e\\u0635\\u064a\\u0629. \\u062a\\u0633\\u062a\\u062e\\u062f\\u0645 \\u0645\\u0646\\u0635\\u062a\\u0646\\u0627 \\u062a\\u062f\\u0627\\u0628\\u064a\\u0631 \\u0623\\u0645\\u0646\\u064a\\u0629 \\u0645\\u062a\\u0642\\u062f\\u0645\\u0629\\u060c \\u0628\\u0645\\u0627 \\u0641\\u064a \\u0630\\u0644\\u0643 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a QRCode\\u060c \\u0648\\u0628\\u0631\\u0648\\u062a\\u0648\\u0643\\u0648\\u0644\\u0627\\u062a KYC \\u0627\\u0644\\u0642\\u0648\\u064a\\u0629\\u060c \\u0648\\u0627\\u0644\\u0645\\u0635\\u0627\\u062f\\u0642\\u0629 \\u0627\\u0644\\u062b\\u0646\\u0627\\u0626\\u064a\\u0629 (2FA)\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0636\\u0645\\u0646 \\u062d\\u0645\\u0627\\u064a\\u0629 \\u0628\\u064a\\u0627\\u0646\\u0627\\u062a\\u0643 \\u0637\\u0648\\u0627\\u0644 \\u0631\\u062d\\u0644\\u0629 \\u0627\\u0644\\u062a\\u062f\\u0627\\u0648\\u0644 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0643."}},"id":"64de00a4c7ce8"},"64de00d5e0853":{"language":{"en":{"question":"What is the Trade Marketplace?","answer":"The Trade Marketplace is where buyers and sellers come together to explore trading opportunities. It features a diverse range of listings, including products, services, and cryptocurrencies, allowing users to find matches that align with their preferences."},"es":{"question":"\\u00bfQu\\u00e9 es el mercado comercial?","answer":"Trade Marketplace es donde los compradores y vendedores se re\\u00fanen para explorar oportunidades comerciales. Cuenta con una amplia gama de listados, incluidos productos, servicios y criptomonedas, lo que permite a los usuarios encontrar coincidencias que se alinean con sus preferencias."},"ar":{"question":"\\u0645\\u0627 \\u0647\\u0648 \\u0633\\u0648\\u0642 \\u0627\\u0644\\u062a\\u062c\\u0627\\u0631\\u0629\\u061f","answer":"\\u0627\\u0644\\u0633\\u0648\\u0642 \\u0627\\u0644\\u062a\\u062c\\u0627\\u0631\\u064a \\u0647\\u0648 \\u0627\\u0644\\u0645\\u0643\\u0627\\u0646 \\u0627\\u0644\\u0630\\u064a \\u064a\\u062c\\u062a\\u0645\\u0639 \\u0641\\u064a\\u0647 \\u0627\\u0644\\u0645\\u0634\\u062a\\u0631\\u0648\\u0646 \\u0648\\u0627\\u0644\\u0628\\u0627\\u0626\\u0639\\u0648\\u0646 \\u0644\\u0627\\u0633\\u062a\\u0643\\u0634\\u0627\\u0641 \\u0627\\u0644\\u0641\\u0631\\u0635 \\u0627\\u0644\\u062a\\u062c\\u0627\\u0631\\u064a\\u0629. \\u0648\\u064a\\u0636\\u0645 \\u0645\\u062c\\u0645\\u0648\\u0639\\u0629 \\u0645\\u062a\\u0646\\u0648\\u0639\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0642\\u0648\\u0627\\u0626\\u0645\\u060c \\u0628\\u0645\\u0627 \\u0641\\u064a \\u0630\\u0644\\u0643 \\u0627\\u0644\\u0645\\u0646\\u062a\\u062c\\u0627\\u062a \\u0648\\u0627\\u0644\\u062e\\u062f\\u0645\\u0627\\u062a \\u0648\\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u0634\\u0641\\u0631\\u0629\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0633\\u0645\\u062d \\u0644\\u0644\\u0645\\u0633\\u062a\\u062e\\u062f\\u0645\\u064a\\u0646 \\u0628\\u0627\\u0644\\u0639\\u062b\\u0648\\u0631 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u062a\\u0637\\u0627\\u0628\\u0642\\u0627\\u062a \\u0627\\u0644\\u062a\\u064a \\u062a\\u062a\\u0648\\u0627\\u0641\\u0642 \\u0645\\u0639 \\u062a\\u0641\\u0636\\u064a\\u0644\\u0627\\u062a\\u0647\\u0645."}},"id":"64de00d5e0853"},"64de00f9efb93":{"language":{"en":{"question":"How do I negotiate offers on Anaki?","answer":"Anaki\\u2019s Offer and Counter Offer system allows for smooth negotiations. Buyers can propose offers, and sellers can respond with counter offers until both parties agree on terms. This feature empowers users to tailor transactions to their liking."},"es":{"question":"\\u00bfC\\u00f3mo negocio ofertas en Anaki?","answer":"El sistema de ofertas y contraofertas de Anaki permite negociaciones fluidas. Los compradores pueden proponer ofertas y los vendedores pueden responder con contraofertas hasta que ambas partes acuerden los t\\u00e9rminos. Esta funci\\u00f3n permite a los usuarios personalizar las transacciones a su gusto."},"ar":{"question":"\\u0643\\u064a\\u0641 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0627\\u0644\\u062a\\u0641\\u0627\\u0648\\u0636 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0639\\u0631\\u0648\\u0636 \\u0639\\u0644\\u0649 Anaki\\u061f","answer":"\\u064a\\u062a\\u064a\\u062d \\u0646\\u0638\\u0627\\u0645 \\u0627\\u0644\\u0639\\u0631\\u0636 \\u0648\\u0627\\u0644\\u0639\\u0631\\u0636 \\u0627\\u0644\\u0645\\u0636\\u0627\\u062f \\u0641\\u064a Anaki \\u0625\\u062c\\u0631\\u0627\\u0621 \\u0645\\u0641\\u0627\\u0648\\u0636\\u0627\\u062a \\u0633\\u0644\\u0633\\u0629. \\u064a\\u0645\\u0643\\u0646 \\u0644\\u0644\\u0645\\u0634\\u062a\\u0631\\u064a\\u0646 \\u0627\\u0642\\u062a\\u0631\\u0627\\u062d \\u0627\\u0644\\u0639\\u0631\\u0648\\u0636\\u060c \\u0648\\u064a\\u0645\\u0643\\u0646 \\u0644\\u0644\\u0628\\u0627\\u0626\\u0639\\u064a\\u0646 \\u0627\\u0644\\u0631\\u062f \\u0628\\u0639\\u0631\\u0648\\u0636 \\u0645\\u0636\\u0627\\u062f\\u0629 \\u062d\\u062a\\u0649 \\u064a\\u062a\\u0641\\u0642 \\u0627\\u0644\\u0637\\u0631\\u0641\\u0627\\u0646 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0634\\u0631\\u0648\\u0637. \\u062a\\u062a\\u064a\\u062d \\u0647\\u0630\\u0647 \\u0627\\u0644\\u0645\\u064a\\u0632\\u0629 \\u0644\\u0644\\u0645\\u0633\\u062a\\u062e\\u062f\\u0645\\u064a\\u0646 \\u062a\\u062e\\u0635\\u064a\\u0635 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u062d\\u0633\\u0628 \\u0631\\u063a\\u0628\\u062a\\u0647\\u0645."}},"id":"64de00f9efb93"},"64de01434ce3c":{"language":{"en":{"question":"Can I trade on the go with Anaki?","answer":"Absolutely. Our dedicated mobile app for Android and iOS devices empowers you to trade anytime, anywhere. Stay connected, manage your trades, and receive real-time updates, all from the convenience of your mobile device."},"es":{"question":"\\u00bfPuedo operar sobre la marcha con Anaki?","answer":"Absolutamente. Nuestra aplicaci\\u00f3n m\\u00f3vil dedicada para dispositivos Android e iOS le permite operar en cualquier momento y en cualquier lugar. Mant\\u00e9ngase conectado, administre sus operaciones y reciba actualizaciones en tiempo real, todo desde la comodidad de su dispositivo m\\u00f3vil."},"ar":{"question":"\\u0647\\u0644 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0627\\u0644\\u062a\\u062f\\u0627\\u0648\\u0644 \\u0623\\u062b\\u0646\\u0627\\u0621 \\u0627\\u0644\\u062a\\u0646\\u0642\\u0644 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 Anaki\\u061f","answer":"\\u0642\\u0637\\u0639\\u0627\\u064b. \\u064a\\u0645\\u0643\\u0651\\u0646\\u0643 \\u062a\\u0637\\u0628\\u064a\\u0642\\u0646\\u0627 \\u0627\\u0644\\u0645\\u062e\\u0635\\u0635 \\u0644\\u0644\\u0647\\u0648\\u0627\\u062a\\u0641 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644\\u0629 \\u0644\\u0623\\u062c\\u0647\\u0632\\u0629 Android \\u0648iOS \\u0645\\u0646 \\u0627\\u0644\\u062a\\u062f\\u0627\\u0648\\u0644 \\u0641\\u064a \\u0623\\u064a \\u0648\\u0642\\u062a \\u0648\\u0641\\u064a \\u0623\\u064a \\u0645\\u0643\\u0627\\u0646. \\u0627\\u0628\\u0642 \\u0639\\u0644\\u0649 \\u0627\\u062a\\u0635\\u0627\\u0644\\u060c \\u0648\\u0642\\u0645 \\u0628\\u0625\\u062f\\u0627\\u0631\\u0629 \\u062a\\u062f\\u0627\\u0648\\u0644\\u0627\\u062a\\u0643\\u060c \\u0648\\u0627\\u062d\\u0635\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u062a\\u062d\\u062f\\u064a\\u062b\\u0627\\u062a \\u0641\\u064a \\u0627\\u0644\\u0648\\u0642\\u062a \\u0627\\u0644\\u0641\\u0639\\u0644\\u064a\\u060c \\u0643\\u0644 \\u0630\\u0644\\u0643 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u062c\\u0647\\u0627\\u0632\\u0643 \\u0627\\u0644\\u0645\\u062d\\u0645\\u0648\\u0644."}},"id":"64de01434ce3c"},"64de016e66c65":{"language":{"en":{"question":"Are there fees associated with trading on Anaki?","answer":"Yes, trading fees may apply to certain transactions on our platform. These fees help maintain the platform and provide you with a seamless trading experience. The Fee Calculator allows you to estimate costs before trading."},"es":{"question":"\\u00bfHay tarifas asociadas con el comercio en Anaki?","answer":"S\\u00ed, se pueden aplicar tarifas comerciales a ciertas transacciones en nuestra plataforma. Estas tarifas ayudan a mantener la plataforma y le brindan una experiencia comercial fluida. La Calculadora de tarifas le permite estimar los costos antes de operar."},"ar":{"question":"\\u0647\\u0644 \\u0647\\u0646\\u0627\\u0643 \\u0631\\u0633\\u0648\\u0645 \\u0645\\u0631\\u062a\\u0628\\u0637\\u0629 \\u0628\\u0627\\u0644\\u062a\\u062f\\u0627\\u0648\\u0644 \\u0639\\u0644\\u0649 Anaki\\u061f","answer":"\\u0646\\u0639\\u0645\\u060c \\u0642\\u062f \\u064a\\u062a\\u0645 \\u062a\\u0637\\u0628\\u064a\\u0642 \\u0631\\u0633\\u0648\\u0645 \\u0627\\u0644\\u062a\\u062f\\u0627\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0628\\u0639\\u0636 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a \\u0627\\u0644\\u062a\\u064a \\u062a\\u062a\\u0645 \\u0639\\u0644\\u0649 \\u0645\\u0646\\u0635\\u062a\\u0646\\u0627. \\u062a\\u0633\\u0627\\u0639\\u062f \\u0647\\u0630\\u0647 \\u0627\\u0644\\u0631\\u0633\\u0648\\u0645 \\u0641\\u064a \\u0627\\u0644\\u062d\\u0641\\u0627\\u0638 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0645\\u0646\\u0635\\u0629 \\u0648\\u062a\\u0648\\u0641\\u0631 \\u0644\\u0643 \\u062a\\u062c\\u0631\\u0628\\u0629 \\u062a\\u062f\\u0627\\u0648\\u0644 \\u0633\\u0644\\u0633\\u0629. \\u062a\\u062a\\u064a\\u062d \\u0644\\u0643 \\u062d\\u0627\\u0633\\u0628\\u0629 \\u0627\\u0644\\u0631\\u0633\\u0648\\u0645 \\u062a\\u0642\\u062f\\u064a\\u0631 \\u0627\\u0644\\u062a\\u0643\\u0627\\u0644\\u064a\\u0641 \\u0642\\u0628\\u0644 \\u0627\\u0644\\u062a\\u062f\\u0627\\u0648\\u0644."}},"id":"64de016e66c65"},"64de018fadb6f":{"language":{"en":{"question":"How do I get started with Anaki?","answer":"Getting started is easy. Simply create an account, explore the Trade Marketplace, initiate a trade, and begin your P2P trading journey. Our user-friendly platform and dedicated support team are here to guide you every step of the way."},"es":{"question":"\\u00bfC\\u00f3mo empiezo con Anaki?","answer":"Comenzar es f\\u00e1cil. Simplemente cree una cuenta, explore Trade Marketplace, inicie una operaci\\u00f3n y comience su viaje comercial P2P. Nuestra plataforma f\\u00e1cil de usar y nuestro equipo de soporte dedicado est\\u00e1n aqu\\u00ed para guiarlo en cada paso del camino"},"ar":{"question":"\\u0643\\u064a\\u0641 \\u0623\\u0628\\u062f\\u0623 \\u0645\\u0639 Anaki\\u061f","answer":"\\u0627\\u0644\\u0628\\u062f\\u0621 \\u0633\\u0647\\u0644. \\u0645\\u0627 \\u0639\\u0644\\u064a\\u0643 \\u0633\\u0648\\u0649 \\u0625\\u0646\\u0634\\u0627\\u0621 \\u062d\\u0633\\u0627\\u0628\\u060c \\u0648\\u0627\\u0633\\u062a\\u0643\\u0634\\u0627\\u0641 Trade Marketplace\\u060c \\u0648\\u0628\\u062f\\u0621 \\u0627\\u0644\\u062a\\u062f\\u0627\\u0648\\u0644\\u060c \\u0648\\u0628\\u062f\\u0621 \\u0631\\u062d\\u0644\\u0629 \\u0627\\u0644\\u062a\\u062f\\u0627\\u0648\\u0644 P2P \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0643. \\u0645\\u0646\\u0635\\u062a\\u0646\\u0627 \\u0633\\u0647\\u0644\\u0629 \\u0627\\u0644\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0648\\u0641\\u0631\\u064a\\u0642 \\u0627\\u0644\\u062f\\u0639\\u0645 \\u0627\\u0644\\u0645\\u062e\\u0635\\u0635 \\u0645\\u0648\\u062c\\u0648\\u062f\\u0648\\u0646 \\u0647\\u0646\\u0627 \\u0644\\u0625\\u0631\\u0634\\u0627\\u062f\\u0643 \\u0641\\u064a \\u0643\\u0644 \\u062e\\u0637\\u0648\\u0629 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0637\\u0631\\u064a\\u0642."}},"id":"64de018fadb6f"},"64de01be0e08f":{"language":{"en":{"question":"What if I encounter issues during a trade?","answer":"Our customer support team is here to assist you. If you encounter any issues, questions, or need guidance, please reach out to us at [email address], and we\\u2019ll be happy to help."},"es":{"question":"\\u00bfQu\\u00e9 sucede si encuentro problemas durante una operaci\\u00f3n?","answer":"Nuestro equipo de atenci\\u00f3n al cliente est\\u00e1 aqu\\u00ed para ayudarlo. Si tiene alg\\u00fan problema, pregunta o necesita orientaci\\u00f3n, comun\\u00edquese con nosotros a [direcci\\u00f3n de correo electr\\u00f3nico] y estaremos encantados de ayudarle."},"ar":{"question":"\\u0645\\u0627\\u0630\\u0627 \\u0644\\u0648 \\u0648\\u0627\\u062c\\u0647\\u062a \\u0645\\u0634\\u0643\\u0644\\u0627\\u062a \\u0623\\u062b\\u0646\\u0627\\u0621 \\u0627\\u0644\\u062a\\u062f\\u0627\\u0648\\u0644\\u061f","answer":"\\u0641\\u0631\\u064a\\u0642 \\u062f\\u0639\\u0645 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u0621 \\u0644\\u062f\\u064a\\u0646\\u0627 \\u0645\\u0648\\u062c\\u0648\\u062f \\u0644\\u0645\\u0633\\u0627\\u0639\\u062f\\u062a\\u0643. \\u0625\\u0630\\u0627 \\u0648\\u0627\\u062c\\u0647\\u062a \\u0623\\u064a \\u0645\\u0634\\u0643\\u0644\\u0627\\u062a \\u0623\\u0648 \\u0623\\u0633\\u0626\\u0644\\u0629 \\u0623\\u0648 \\u0643\\u0646\\u062a \\u0628\\u062d\\u0627\\u062c\\u0629 \\u0625\\u0644\\u0649 \\u0625\\u0631\\u0634\\u0627\\u062f\\u0627\\u062a\\u060c \\u0641\\u064a\\u0631\\u062c\\u0649 \\u0627\\u0644\\u062a\\u0648\\u0627\\u0635\\u0644 \\u0645\\u0639\\u0646\\u0627 \\u0639\\u0644\\u0649 [email title]\\u060c \\u0648\\u0633\\u0646\\u0643\\u0648\\u0646 \\u0633\\u0639\\u062f\\u0627\\u0621 \\u0628\\u062a\\u0642\\u062f\\u064a\\u0645 \\u0627\\u0644\\u0645\\u0633\\u0627\\u0639\\u062f\\u0629."}},"id":"64de01be0e08f"},"64de01e3da3d2":{"language":{"en":{"question":"Is Anaki available internationally?","answer":"Yes, Anaki is accessible to users around the world. Our platform fosters connections between buyers and sellers globally, facilitating cross-border transactions with ease."},"es":{"question":"\\u00bfAnaki est\\u00e1 disponible internacionalmente?","answer":"S\\u00ed, Anaki es accesible para usuarios de todo el mundo. Nuestra plataforma fomenta las conexiones entre compradores y vendedores a nivel mundial, facilitando las transacciones transfronterizas con facilidad"},"ar":{"question":"\\u0647\\u0644 Anaki \\u0645\\u062a\\u0627\\u062d \\u062f\\u0648\\u0644\\u064a\\u064b\\u0627\\u061f","answer":"Yes, Anaki is accessible to users around the world. Our platform fosters connections between buyers and sellers globally, facilitating cross-border transactions with ease."}},"id":"64de01e3da3d2"}},"language":{"en":{"title":"FAQ","heading":"Frequently Asked Questions (FAQs)","sub_heading":"Frequently Asked Questions (FAQs)"},"es":{"title":"FAQ","heading":"Preguntas frecuentes (FAQ)","sub_heading":"Explore nuestra secci\\u00f3n de preguntas frecuentes concisas para encontrar r\\u00e1pidamente respuestas a preguntas comunes sobre la plataforma de comercio entre pares de Anaki"},"ar":{"title":"\\u0627\\u0644\\u062a\\u0639\\u0644\\u064a\\u0645\\u0627\\u062a","heading":"\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0627\\u0648\\u0644\\u0629 (\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0634\\u0627\\u0626\\u0639\\u0629)","sub_heading":"\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062f\\u0627\\u0648\\u0644\\u0629 (\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0634\\u0627\\u0626\\u0639\\u0629)"}}}','status' => '1','serialize' => NULL,'created_at' => '2023-08-12 10:33:40','updated_at' => '2023-11-25 05:13:23'),
